package fable.hideseek.imba.mixin;
import fable.hideseek.imba.mask.MaskState;import fable.hideseek.imba.mask.MaskService;import fable.hideseek.imba.mask.MaskType;import net.minecraft.block.Block;import net.minecraft.item.Item;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.text.Text;import org.spongepowered.asm.mixin.Mixin;import org.spongepowered.asm.mixin.injection.At;import org.spongepowered.asm.mixin.injection.Inject;import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
@Mixin(MaskService.class) public abstract class MaskServiceGuardMixin {@Inject(method="applyMask",at=@At("HEAD"),cancellable=true)private static void imba$preventSecondMask(ServerPlayerEntity player,MaskType type,Block block,Item item,CallbackInfo ci){if(MaskState.hasMask(player.getUuid())){player.sendMessage(Text.literal("§cМаскировка уже надета. Повторно надеть модель нельзя."),true);ci.cancel();}}}
